function solve(routes, source, target) {
  if (source === target) return 0;
  const seen = new Set([source]);
  let frontier = [source];
  let rides = 0;
  while (frontier.length > 0) {
    rides++;
    const next = [];
    for (const stop of frontier) {
      for (let i = 0; i < routes.length; i++) {
        const route = routes[i];
        let onRoute = false;
        for (const s of route) {
          if (s === stop) {
            onRoute = true;
            break;
          }
        }
        if (!onRoute) continue;
        for (const s of route) {
          if (s === target) return rides;
          if (!seen.has(s)) {
            seen.add(s);
            next.push(s);
          }
        }
      }
    }
    frontier = next;
  }
  return -1;
}

function solve(routes, source, target) {
  if (source === target) return 0;
  const stopRoutes = new Map();
  for (let i = 0; i < routes.length; i++) {
    for (const stop of routes[i]) {
      if (!stopRoutes.has(stop)) stopRoutes.set(stop, []);
      stopRoutes.get(stop).push(i);
    }
  }
  const dist = new Array(routes.length).fill(-1);
  let frontier = [];
  const startRoutes = stopRoutes.get(source);
  if (startRoutes !== undefined) {
    for (const r of startRoutes) {
      dist[r] = 1;
      frontier.push(r);
    }
  }
  let rides = 1;
  while (frontier.length > 0) {
    const next = [];
    for (const r of frontier) {
      for (const stop of routes[r]) {
        if (stop === target) return rides;
        const owners = stopRoutes.get(stop);
        if (owners === undefined) continue;
        for (const other of owners) {
          if (dist[other] === -1) {
            dist[other] = rides + 1;
            next.push(other);
          }
        }
      }
    }
    frontier = next;
    rides++;
  }
  return -1;
}
